import { FieldListColumn } from '../types/FieldList'

// Test 1: FieldListColumn with `dependent` should work
FieldListColumn({
    dependent: 'some_table_column',
    label: 'Fields with Runtime Table Context',
    maxLength: 4000,
})

// Test 2: FieldListColumn with `attributes.table` should work
FieldListColumn({
    attributes: {
        table: 'sn_sales_forecast_header',
    },
    label: 'Fields with Static Table Context',
    maxLength: 4000,
})

// Test 3: FieldListColumn with `attributes` but without `table` should work (no table context required)
FieldListColumn({
    attributes: {
        some_other_attr: 'value',
    },
    label: 'Attributes without table',
    maxLength: 4000,
})

// Test 4: FieldListColumn with neither `dependent` nor `attributes.table` should work (both are optional)
FieldListColumn({
    label: 'No Table Context',
    maxLength: 4000,
})

// Test 5: FieldListColumn with empty object should work (dependent is non-mandatory)
FieldListColumn({})

// Test 6: FieldListColumn with `dependent` and other attributes (not table) should work
FieldListColumn({
    dependent: 'some_column',
    attributes: {
        edge_encryption_enabled: true,
    },
    label: 'Dependent with other attributes',
    maxLength: 4000,
})

// Test 7: FieldListColumn with both `dependent` and `attributes.table` should fail
// @ts-expect-error Cannot have both dependent and attributes.table
FieldListColumn({
    dependent: 'some_column',
    attributes: {
        table: 'incident',
    },
    label: 'Both specified',
    maxLength: 4000,
})
